mapper.sql:
WHERE 1=1
AND (LOWER(f.name) LIKE #{q} ESCAPE '\\' OR LOWER(COALESCE(f.farm_code,'')) LIKE #{q} ESCAPE '\\')
AND f.organization_id=#{organizationId}
AND f.owner_user_id=#{ownerUserId}
AND f.lifecycle_status=#{lifecycleStatus}
AND f.status=#{status}

WHERE 1=1
AND a.organization_id=#{organizationId}
AND a.farm_id=#{farmId}
AND a.actor_user_id=#{actorUserId}
AND a.action=#{action}
AND a.target_type=#{targetType}
AND a.target_id=#{targetId}
AND a.created_at>=#{createdFrom}
AND a.created_at<#{createdToExclusive}

mapper.select:
SELECT a.*,o.name organization_name,f.name farm_name,u.display_name actor_name,u.email actor_email,CAST(a.detail_json AS CHAR) detail_json
FROM audit_log a LEFT JOIN organization o ON o.id=a.organization_id LEFT JOIN farm f ON f.id=a.farm_id LEFT JOIN users u ON u.id=a.actor_user_id
 ORDER BY ${orderBy} ${direction},a.id ${direction} LIMIT #{size} OFFSET #{offset}
